('PT158-S4-Q22','D','37d8d9898f0fb7ac1c3ddf2a8dd5fec5',false),
('PT158-S4-Q22','E','bfbc6825754955ce9445094d802761ca',true),
('PT158-S4-Q24','A','7317811e807510f162b53246b93d3887',false),
('PT158-S4-Q24','B','79c99ab66a569459e588b15e44c5d00a',false),
('PT158-S4-Q24','C','0b8d6a82966b863dc57d6ffeec23c552',false),
